-- Carefully selected historic entries from the Magic Motorsport FLEX published vehicle list.
-- Snapshot is a 2020 vendor list, NOT a guarantee of current compatibility or read/write capability.
create table if not exists public.vehicle_ecu_references (
 id bigint generated always as identity primary key,
 reference_key text not null unique,
 make text not null,
 model text not null,
 generation text,
 engine_code text,
 engine_label text,
 power_ps integer,
 listed_year integer,
 ecu_manufacturer text,
 ecu_family text not null,
 tool_name text not null,
 connection_method text not null check (connection_method in ('OBD','Bench','Boot','BDM')),
 read_capability text not null default 'unknown' check (read_capability in ('unknown','physical','virtual','no')),
 write_capability text not null default 'unknown' check (write_capability in ('unknown','yes','no')),
 coverage_status text not null default 'historic_vendor_list' check (coverage_status in ('historic_vendor_list','current_vendor_list','exact_hw_sw_verified')),
 source_url text not null,
 source_label text not null,
 source_year integer,
 reviewed_at timestamptz,
 updated_at timestamptz not null default now()
);
alter table public.vehicle_ecu_references enable row level security;
revoke all on public.vehicle_ecu_references from public, anon, authenticated;
create index if not exists vehicle_ecu_refs_engine_idx on public.vehicle_ecu_references (lower(engine_code));
create index if not exists vehicle_ecu_refs_ecu_idx on public.vehicle_ecu_references (lower(ecu_family));
create index if not exists vehicle_ecu_refs_make_model_idx on public.vehicle_ecu_references (lower(make),lower(model));
-- Only the server's service role may expose curated, non-customer catalogue entries.
on conflict (reference_key) do update set source_url=excluded.source_url, source_label=excluded.source_label;
